<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">  valuesContent</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">|-</span></span>
